// Initialize health check results
return [
  { check_type: 'instagram_api', status: 'unknown', response_time_ms: null, error_message: null },
  { check_type: 'whatsapp_api', status: 'unknown', response_time_ms: null, error_message: null },
  { check_type: 'mpesa_api', status: 'unknown', response_time_ms: null, error_message: null },
  { check_type: 'database', status: 'unknown', response_time_ms: null, error_message: null },
  { check_type: 'workflow', status: 'unknown', response_time_ms: null, error_message: null }
];

// Process health check results
const checks = [];
const startTime = Date.now();

// Process Instagram check
const instagramResult = $('Check Instagram API').first()?.json || {};
const instagramTime = Date.now() - startTime;
checks.push({
  check_type: 'instagram_api',
  status: instagramResult.id ? 'healthy' : 'down',
  response_time_ms: instagramTime,
  error_message: instagramResult.error ? JSON.stringify(instagramResult.error) : null,
  metadata: { user_id: instagramResult.id, username: instagramResult.username }
});

// Process WhatsApp check
const whatsappResult = $('Check WhatsApp API').first()?.json || {};
const whatsappTime = Date.now() - startTime;
checks.push({
  check_type: 'whatsapp_api',
  status: whatsappResult.id ? 'healthy' : 'down',
  response_time_ms: whatsappTime,
  error_message: whatsappResult.error ? JSON.stringify(whatsappResult.error) : null,
  metadata: { page_id: whatsappResult.id }
});

// Process M-Pesa check
const mpesaResult = $('Check M-Pesa API').first()?.json || {};
const mpesaTime = Date.now() - startTime;
checks.push({
  check_type: 'mpesa_api',
  status: mpesaResult.access_token ? 'healthy' : 'down',
  response_time_ms: mpesaTime,
  error_message: mpesaResult.error ? JSON.stringify(mpesaResult.error) : null,
  metadata: { token_type: mpesaResult.token_type }
});

// Process Database check
const dbResult = $('Check Database').first()?.json || {};
const dbTime = Date.now() - startTime;
checks.push({
  check_type: 'database',
  status: dbResult.version ? 'healthy' : 'down',
  response_time_ms: dbTime,
  error_message: dbResult.error ? JSON.stringify(dbResult.error) : null,
  metadata: { version: dbResult.version }
});

// Process Workflow check
const workflowResult = $('Check Workflow Execution').first()?.json || [];
const workflowTime = Date.now() - startTime;
checks.push({
  check_type: 'workflow',
  status: Array.isArray(workflowResult) ? 'healthy' : 'degraded',
  response_time_ms: workflowTime,
  error_message: null,
  metadata: { orders_last_24h: workflowResult.length }
});

return checks;

// Check for failures and create support cases
const checks = $input.all();
const failures = checks.filter(c => c.status === 'down' || c.status === 'degraded');

if (failures.length > 0) {
  return failures.map(failure => ({
    check_type: failure.check_type,
    status: failure.status,
    error_message: failure.error_message,
    should_alert: true,
    alert_message: `⚠️ Health Check Failed: ${failure.check_type} is ${failure.status}. ${failure.error_message || 'No details available'}`
  }));
}

return [{ should_alert: false, message: 'All systems healthy' }];

// Summary
const allChecks = $('Process Health Check Results').all();
const healthy = allChecks.filter(c => c.status === 'healthy').length;
const total = allChecks.length;

return {
  total_checks: total,
  healthy: healthy,
  degraded: allChecks.filter(c => c.status === 'degraded').length,
  down: allChecks.filter(c => c.status === 'down').length,
  timestamp: new Date().toISOString()
};
